import{_ as t,o as a,c as r,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"Billing and Credits Architecture","description":"Core concepts of the dual-model billing architecture using Tiers and Credits.","frontmatter":{"type":"Specification","title":"Billing and Credits Architecture","description":"Core concepts of the dual-model billing architecture using Tiers and Credits.","tags":["architecture","billing","credits"],"isInternal":true},"headers":[],"relativePath":"specs/billing_and_credits.md","filePath":"specs/billing_and_credits.md"}'),o={name:"specs/billing_and_credits.md"};function n(s,e,c,l,d,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="billing-and-credits-architecture" tabindex="-1">Billing and Credits Architecture <a class="header-anchor" href="#billing-and-credits-architecture" aria-label="Permalink to &quot;Billing and Credits Architecture&quot;">​</a></h1><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><p>Sanjeev AI uses a dual-model billing architecture:</p><ol><li><strong>Tiers (<code>plan</code>)</strong>: <code>&quot;basic&quot;</code> or <code>&quot;pro&quot;</code>. Tiers are feature gates. They DO NOT dictate how much a user pays per token. Pro tier unlocks advanced agent capabilities (e.g., parallel agents, specialized roles).</li><li><strong>Credits (<code>credits</code>)</strong>: A numerical value stored on the <code>users/{uid}</code> document representing prepaid tokens.</li></ol><h2 id="token-based-consumption" tabindex="-1">Token-Based Consumption <a class="header-anchor" href="#token-based-consumption" aria-label="Permalink to &quot;Token-Based Consumption&quot;">​</a></h2><p>Every invocation of the Gemini API (or other LLMs) will consume credits exactly equal to <code>usageMetadata.totalTokenCount</code>.</p><h2 id="overdraft-buffer" tabindex="-1">Overdraft Buffer <a class="header-anchor" href="#overdraft-buffer" aria-label="Permalink to &quot;Overdraft Buffer&quot;">​</a></h2><p>To prevent jarring UX when a task is 99% complete but runs out of credits, we allow an <strong>Overdraft Buffer</strong> of <code>-5000</code> credits.</p><ul><li>If a user has <code>10</code> credits, they can start a task.</li><li>If that task costs <code>3000</code> tokens, their balance becomes <code>-2990</code>. The task completes successfully.</li><li>However, if <code>credits &lt;= 0</code>, the UI and backend will reject any NEW task initialization requests.</li></ul><h2 id="batching-strategy" tabindex="-1">Batching Strategy <a class="header-anchor" href="#batching-strategy" aria-label="Permalink to &quot;Batching Strategy&quot;">​</a></h2><p>Deducting credits per-token or per-LLM-call would result in exorbitant Firestore write costs.</p><ul><li><strong>Implementation</strong>: Instead of writing to Firestore on every call, the <code>generator.ts</code> and <code>parser.ts</code> agents will accumulate token usage in memory during a single HTTP request lifecycle.</li><li><strong>Write Phase</strong>: Right before sending the final HTTP response to the client, a single Firestore <code>FieldValue.increment(-totalSessionTokens)</code> update is dispatched to the user&#39;s document.</li></ul>',12)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
